interface.definition:
a!localVariables(
  local!org: ri!org,
  local!isParent: a!defaultValue(local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/56279cd7-e7c5-4577-9c40-eae4b315ac12"], false),
  local!orgId: local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/5793af42-009b-4cef-b5b5-7c4a81f902ec"],
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      /* Colored strip */
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: #"SYSTEM_SYSRULES_sideBySideLayout"(
          alignVertical: "MIDDLE",
          items: {
            #"SYSTEM_SYSRULES_sideBySideItem"(
              item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                marginBelow: "NONE",
                value: {
                  #"SYSTEM_SYSRULES_richTextItem_v1"(text: local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/0f073a93-5255-4fd3-bdba-87d2febf50e9"], color: "#FFFFFF", style: "STRONG", size: "MEDIUM"),
                  char(10),
                  #"SYSTEM_SYSRULES_richTextItem_v1"(text: local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/47e00641-832e-4dbe-a4e1-c0ff7da8deba"], color: "#FFFFFF", size: "SMALL")
                }
              )
            ),
            #"SYSTEM_SYSRULES_sideBySideItem"(
              width: "MINIMIZE",
              item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                align: "RIGHT",
                marginBelow: "NONE",
                value: #"SYSTEM_SYSRULES_richTextItem_v1"(text: if(local!isParent, "PARENT", "CHILD"), color: "#FFFFFF", style: "STRONG", size: "SMALL")
              )
            )
          }
        ),
        style: if(local!isParent, "#3F7D2A", "#2E7DBB"),
        padding: "STANDARD",
        showBorder: false
      ),
      /* Body */
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            marginBelow: "STANDARD",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(icon: "user-circle", color: "#6AA84F"),
              " ",
              #"SYSTEM_SYSRULES_richTextItem_v1"(text: a!defaultValue(#"_a-0000eef8-4604-8000-9e54-011c48011c48_1121809"(local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/4b67e544-964e-485d-90df-3947cc4b80b2"]), "-"))
            }
          ),
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1352797"(
                  value: a!defaultValue(count(#"_a-0000eef8-4604-8000-9e54-011c48011c48_1134349"(orgid: local!orgId, isActive: true())), 0),
                  label: "TEAMS"
                )
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1352797"(
                  value: a!defaultValue(count(#"_a-0000eef8-4604-8000-9e54-011c48011c48_1142076"(orgid: local!orgId, isActive: true())), 0),
                  label: "APPS"
                )
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1352797"(
                  value: a!defaultValue(count(#"_a-0000eef8-4604-8000-9e54-011c48011c48_1152489"(orgid: local!orgId, isActive: true())), 0),
                  label: "USERS"
                )
              )
            }
          ),
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            marginBelow: "NONE",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(icon: "map-marker", color: "SECONDARY"),
              " ",
              #"SYSTEM_SYSRULES_richTextItem_v1"(text: a!defaultValue(local!org[#"urn:appian:record-field:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/60f9ea53-2ab2-479b-a990-a1eac9caaa33/f19ea19e-f942-445d-a2b3-1e55c08cf38b"], "—"), color: "SECONDARY", size: "SMALL")
            }
          )
        },
        style: "NONE",
        padding: "STANDARD",
        showBorder: false
      ),
      /* Footer: Update */
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: #"SYSTEM_SYSRULES_recordActionField_v1"(
          actions: #"SYSTEM_SYSRULES_recordActionItem"(
            action: #"urn:appian:record-action:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f/c02fbc37-63a5-41e2-b927-300bacd31d79",
            identifier: local!orgId
          ),
          style: "TOOLBAR",
          align: "END"
        ),
        style: "NONE",
        padding: "STANDARD",
        showBorder: false
      )
    },
    link: #"SYSTEM_SYSRULES_recordLink"(
      recordType: #"urn:appian:record-type:v1:008dc9c2-5821-421b-b1dd-e322b8e6665f",
      identifier: local!orgId
    ),
    style: "NONE",
    shape: "SEMI_ROUNDED",
    padding: "NONE",
    showBorder: true,
    showShadow: true
  )
)
